const merged: Record<Lang, Dict> = {
  en,
  ar: { ...en, ...ar },
  fr: { ...en, ...fr },
  es: { ...en, ...es },
  tr: { ...en, ...tr },
  ur: { ...en, ...ur },
};

export function t(key: DictKey, lang: string): string {
  const d = merged[lang as Lang] ?? en;
  return d[key] ?? en[key] ?? key;
}

const tCache = new Map<string, (key: DictKey) => string>();
/** Stable per-language translate function (same reference between renders → safe in effect deps). */
export function useT(): (key: DictKey) => string {
  const lang = useSettingsStore((s) => s.language);
  let fn = tCache.get(lang);
  if (!fn) {
    fn = (key: DictKey) => t(key, lang);
    tCache.set(lang, fn);
  }
  return fn;
}

export function useLang(): { lang: Lang; rtl: boolean } {
  const lang = (useSettingsStore((s) => s.language) as Lang) ?? "en";
  return { lang, rtl: RTL_LANGS.includes(lang) };
}

export function applyDocumentLang(lang: string) {
  if (typeof document === "undefined") return;
  document.documentElement.lang = lang;
  document.documentElement.dir = RTL_LANGS.includes(lang as Lang) ? "rtl" : "ltr";
}
